-- 001 — the control plane.
--
-- Written to run unchanged on SQLite and Postgres. The restrictions that make that
-- possible, and why they are worth it:
--
--   * every identifier is a TEXT uuid generated by the application, never a
--     database sequence, so there is no AUTOINCREMENT/IDENTITY split;
--   * every timestamp is TEXT holding ISO-8601 UTC, so there is no
--     DATETIME/timestamptz split and a column is identical in a dump from either;
--   * every boolean is INTEGER 0/1, so a repository reads a flag as a number in
--     both drivers rather than handling `true` in one place and `1` in another;
--   * every amount of money is INTEGER cents, so no float ever touches a price;
--   * JSON is TEXT, validated by the application, not by the column.
--
-- The cost is losing Postgres-native types. That cost is paid once, here; a second
-- migration set for the second driver would be paid on every future schema change.

CREATE TABLE IF NOT EXISTS schema_migrations (
  version     TEXT PRIMARY KEY,
  applied_at  TEXT NOT NULL,
  checksum    TEXT NOT NULL
);

-- ---------------------------------------------------------------------------
-- Identity
-- ---------------------------------------------------------------------------

-- One shed company. This replaces the licence server's `Account` row.
CREATE TABLE IF NOT EXISTS tenants (
  id                    TEXT PRIMARY KEY,
  name                  TEXT NOT NULL,
  slug                  TEXT NOT NULL UNIQUE,
  abn                   TEXT,
  status                TEXT NOT NULL DEFAULT 'active',  -- active | suspended
  -- How many people may hold a session at once. Enforced on sign-in, inside a
  -- transaction, against the live session count -- not by counting a stale column.
  seats                 INTEGER NOT NULL DEFAULT 1,
  subscription_ends_at  TEXT,
  suspended_reason      TEXT,
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS users (
  id                    TEXT PRIMARY KEY,
  email                 TEXT NOT NULL UNIQUE,   -- always lowercased by the application
  display_name          TEXT NOT NULL,
  -- Self-describing: 'scrypt$N$r$p$salt_b64$hash_b64'. The parameters travel with
  -- the hash so the cost can be raised without invalidating every existing row.
  password_hash         TEXT,
  must_change_password  INTEGER NOT NULL DEFAULT 0,
  password_set_at       TEXT,
  platform_role         TEXT,                   -- platform_admin | platform_support | NULL
  disabled_at           TEXT,
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL
);

-- Which companies a person may enter, and as what. The composite primary key is a
-- statement: one person holds exactly one role per company.
CREATE TABLE IF NOT EXISTS memberships (
  tenant_id   TEXT NOT NULL,
  user_id     TEXT NOT NULL,
  role        TEXT NOT NULL,                    -- company_admin | estimator | viewer
  status      TEXT NOT NULL DEFAULT 'active',   -- active | removed
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  PRIMARY KEY (tenant_id, user_id),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS memberships_user ON memberships (user_id);

-- A sign-in session. Only the hash of the token is stored: a leaked database then
-- yields no usable session, which is the difference between an incident and a
-- breach.
CREATE TABLE IF NOT EXISTS sessions (
  id             TEXT PRIMARY KEY,
  token_hash     TEXT NOT NULL UNIQUE,
  user_id        TEXT NOT NULL,
  tenant_id      TEXT,
  created_at     TEXT NOT NULL,
  last_seen_at   TEXT NOT NULL,
  expires_at     TEXT NOT NULL,
  revoked_at     TEXT,
  ip_hash        TEXT,
  user_agent     TEXT,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS sessions_user ON sessions (user_id);
CREATE INDEX IF NOT EXISTS sessions_tenant_active ON sessions (tenant_id, revoked_at, expires_at);

-- A single-use grant link. Revocable, and expired links are refused rather than
-- deleted so "this link was used on the 3rd" stays answerable.
CREATE TABLE IF NOT EXISTS invitations (
  id            TEXT PRIMARY KEY,
  token_hash    TEXT NOT NULL UNIQUE,
  tenant_id     TEXT,
  email         TEXT NOT NULL,
  role          TEXT NOT NULL,
  kind          TEXT NOT NULL,                  -- member | platform | reset
  invited_by    TEXT,
  created_at    TEXT NOT NULL,
  expires_at    TEXT NOT NULL,
  accepted_at   TEXT,
  revoked_at    TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (invited_by) REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS invitations_token ON invitations (token_hash);

-- ---------------------------------------------------------------------------
-- Company configuration
-- ---------------------------------------------------------------------------

-- Versioned on purpose. A quote revision records the settings version it was priced
-- under, so changing the company margin today does not rewrite the explanation of
-- yesterday's price.
CREATE TABLE IF NOT EXISTS company_settings (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL,
  version       INTEGER NOT NULL,
  settings_json TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  created_by    TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS company_settings_version ON company_settings (tenant_id, version);

CREATE TABLE IF NOT EXISTS customers (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL,
  first_name          TEXT NOT NULL,
  last_name           TEXT NOT NULL,
  email               TEXT NOT NULL,
  phone               TEXT,
  mobile              TEXT,
  address             TEXT NOT NULL,
  suburb              TEXT,
  state               TEXT,
  postcode            TEXT,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS customers_tenant_email ON customers (tenant_id, email);

-- ---------------------------------------------------------------------------
-- Quotes
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS quotes (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL,
  number            TEXT NOT NULL,
  customer_id       TEXT,
  status            TEXT NOT NULL DEFAULT 'draft',
  current_revision  INTEGER NOT NULL DEFAULT 0,
  -- Kept on the header so a list does not have to read every revision.
  contract_cents    INTEGER,
  incomplete        INTEGER NOT NULL DEFAULT 1,
  site_json         TEXT NOT NULL,
  created_by        TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL,
  -- The same company cannot reuse a quote number. This is the constraint whose
  -- absence let the old server create two "Q-1042"s.
  UNIQUE (tenant_id, number)
);

CREATE INDEX IF NOT EXISTS quotes_tenant_updated ON quotes (tenant_id, updated_at);
CREATE INDEX IF NOT EXISTS quotes_tenant_status ON quotes (tenant_id, status);

-- Per-company, per-year numbering. A row per year, updated inside the same
-- transaction that inserts the quote.
CREATE TABLE IF NOT EXISTS quote_counters (
  tenant_id  TEXT NOT NULL,
  year       INTEGER NOT NULL,
  last_value INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (tenant_id, year),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

-- The record of what a customer was sent.
--
-- Nothing here is ever updated or deleted. The immutability is enforced in the
-- repository (no UPDATE or DELETE statement exists) *and* at the database level by
-- a trigger added in the dialect-specific migration, because code review is not a
-- constraint.
CREATE TABLE IF NOT EXISTS quote_revisions (
  id                TEXT PRIMARY KEY,
  quote_id          TEXT NOT NULL,
  tenant_id         TEXT NOT NULL,
  revision          INTEGER NOT NULL,
  name              TEXT NOT NULL DEFAULT '',
  description       TEXT NOT NULL DEFAULT '',
  -- Frozen inputs and outputs. A price-book update next month must not move these.
  config_json       TEXT NOT NULL,
  bom_json          TEXT NOT NULL,
  price_json        TEXT NOT NULL,
  issues_json       TEXT NOT NULL,
  customer_json     TEXT NOT NULL,
  company_json      TEXT NOT NULL,
  provenance_json   TEXT NOT NULL,
  config_hash       TEXT NOT NULL,
  result_hash       TEXT NOT NULL,
  bom_hash          TEXT NOT NULL,
  price_book_hash   TEXT NOT NULL,
  override_version  INTEGER NOT NULL DEFAULT 0,
  settings_version  INTEGER NOT NULL DEFAULT 0,
  engine_version    INTEGER NOT NULL,
  contract_cents    INTEGER NOT NULL,
  total_cost_cents  INTEGER NOT NULL,
  total_mass_kg     REAL NOT NULL,
  mocked_lines      INTEGER NOT NULL DEFAULT 0,
  idempotency_key   TEXT NOT NULL,
  created_by        TEXT,
  created_by_email  TEXT NOT NULL,
  created_at        TEXT NOT NULL,
  FOREIGN KEY (quote_id) REFERENCES quotes(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  -- Two revisions may not claim the same number, and one idempotency key may
  -- produce exactly one revision, so a double-click is not a second quote.
  UNIQUE (quote_id, revision),
  UNIQUE (tenant_id, idempotency_key)
);

CREATE INDEX IF NOT EXISTS quote_revisions_quote ON quote_revisions (quote_id, revision);

-- A short-lived price preview. Separate from a revision so a preview can expire
-- without touching a quote, and so the table that must never be written can stay
-- small.
CREATE TABLE IF NOT EXISTS evaluations (
  id                TEXT PRIMARY KEY,
  tenant_id         TEXT NOT NULL,
  config_hash       TEXT NOT NULL,
  result_hash       TEXT NOT NULL,
  price_book_hash   TEXT NOT NULL,
  override_version  INTEGER NOT NULL DEFAULT 0,
  settings_version  INTEGER NOT NULL DEFAULT 0,
  engine_version    INTEGER NOT NULL,
  status            TEXT NOT NULL,
  price_json        TEXT NOT NULL,
  lines_json        TEXT NOT NULL,
  issues_json       TEXT NOT NULL,
  created_by        TEXT,
  created_at        TEXT NOT NULL,
  expires_at        TEXT NOT NULL,
  consumed_at       TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS evaluations_tenant ON evaluations (tenant_id, created_at);

-- ---------------------------------------------------------------------------
-- Prices
-- ---------------------------------------------------------------------------

-- A published, content-addressed price book. The file lives on disk named by its
-- hash; this row says who published it and whether it may be shown to a stranger.
CREATE TABLE IF NOT EXISTS price_books (
  hash                  TEXT PRIMARY KEY,
  kind                  TEXT NOT NULL,              -- sample | licensed
  published_at          TEXT NOT NULL,
  published_by          TEXT,
  published_by_email    TEXT NOT NULL,
  table_count           INTEGER NOT NULL,
  row_count             INTEGER NOT NULL,
  supplier_code_count   INTEGER NOT NULL,
  note                  TEXT
);

-- The one book currently served to every company. One row, enforced by the primary
-- key being a constant.
CREATE TABLE IF NOT EXISTS price_book_active (
  id         TEXT PRIMARY KEY,                      -- always 'singleton'
  hash       TEXT NOT NULL,
  activated_at TEXT NOT NULL,
  activated_by TEXT,
  FOREIGN KEY (hash) REFERENCES price_books(hash)
);

-- A versioned set of per-company price overrides. A quote revision names the
-- version it used, so an override written today cannot change an old explanation.
CREATE TABLE IF NOT EXISTS price_overrides (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL,
  version       INTEGER NOT NULL,
  created_at    TEXT NOT NULL,
  created_by    TEXT,
  note          TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS price_overrides_version ON price_overrides (tenant_id, version);

-- One company's price for one book row. The row key is the book's own natural key
-- (`source:field=value&…`), never a row id: a published book is content-addressed
-- and a new publication renumbers ids.
CREATE TABLE IF NOT EXISTS price_row_overrides (
  override_id     TEXT NOT NULL,
  tenant_id       TEXT NOT NULL,
  row_key         TEXT NOT NULL,
  unit_cost_cents INTEGER NOT NULL,
  code_override   TEXT,
  updated_at      TEXT NOT NULL,
  PRIMARY KEY (override_id, row_key),
  FOREIGN KEY (override_id) REFERENCES price_overrides(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS price_row_overrides_tenant ON price_row_overrides (tenant_id);

-- An item this company buys that the shared book has never heard of. Keyed on the
-- NAME the engine asks for, not the customer's SKU: a row keyed on a SKU sits in
-- the table looking configured while every quote falls back to an unpriced line.
CREATE TABLE IF NOT EXISTS company_catalogue_rows (
  tenant_id       TEXT NOT NULL,
  source          TEXT NOT NULL,
  name            TEXT NOT NULL,
  code            TEXT NOT NULL,
  description     TEXT NOT NULL,
  unit            TEXT NOT NULL,
  unit_cost_cents INTEGER NOT NULL,
  mass_kg         REAL NOT NULL DEFAULT 0,
  updated_at      TEXT NOT NULL,
  PRIMARY KEY (tenant_id, source, name),
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------------
-- Customers of our customer: share links
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS quote_shares (
  id           TEXT PRIMARY KEY,
  tenant_id    TEXT NOT NULL,
  quote_id     TEXT NOT NULL,
  revision_id  TEXT NOT NULL,
  token_hash   TEXT NOT NULL UNIQUE,
  created_by   TEXT,
  created_at   TEXT NOT NULL,
  expires_at   TEXT NOT NULL,
  revoked_at   TEXT,
  last_viewed_at TEXT,
  view_count   INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (quote_id) REFERENCES quotes(id) ON DELETE CASCADE,
  FOREIGN KEY (revision_id) REFERENCES quote_revisions(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS quote_shares_quote ON quote_shares (quote_id);

-- ---------------------------------------------------------------------------
-- Outbound mail
-- ---------------------------------------------------------------------------

-- A durable queue. The send runs inline so the operator gets the relay's real
-- answer, but the row exists so a crash mid-send is recoverable rather than lost.
CREATE TABLE IF NOT EXISTS send_jobs (
  id               TEXT PRIMARY KEY,
  tenant_id        TEXT NOT NULL,
  quote_id         TEXT NOT NULL,
  revision_id      TEXT NOT NULL,
  revision_hash    TEXT NOT NULL,
  to_email         TEXT NOT NULL,
  from_email       TEXT NOT NULL,
  reply_to         TEXT,
  subject          TEXT NOT NULL,
  body            TEXT NOT NULL,
  state            TEXT NOT NULL,                    -- queued | sending | accepted | failed | unknown | cancelled
  attempts         INTEGER NOT NULL DEFAULT 0,
  last_error       TEXT,
  created_by       TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  sent_at          TEXT,
  FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (quote_id) REFERENCES quotes(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS send_jobs_state ON send_jobs (state, created_at);

-- ---------------------------------------------------------------------------
-- Templates: the cloud catalogue
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS template_types (
  id          TEXT PRIMARY KEY,
  code        TEXT NOT NULL UNIQUE,
  name        TEXT NOT NULL,
  sort_order  INTEGER NOT NULL DEFAULT 0
);

-- A published quote template. Cloning copies structure and options and **never** the
-- customer's identity, and drops the SiteCheck building id so a new quote cannot
-- inherit another site's wind certificate.
CREATE TABLE IF NOT EXISTS quote_templates (
  id                      TEXT PRIMARY KEY,
  code                    TEXT NOT NULL UNIQUE,
  name                    TEXT NOT NULL,
  type_id                 TEXT NOT NULL,
  status                  TEXT NOT NULL DEFAULT 'draft',   -- draft | active | archived
  thumbnail_path          TEXT,
  basic_config_json       TEXT,
  active_file_revision_id TEXT,
  created_at              TEXT NOT NULL,
  updated_at              TEXT NOT NULL,
  FOREIGN KEY (type_id) REFERENCES template_types(id)
);

CREATE TABLE IF NOT EXISTS quote_template_files (
  id            TEXT PRIMARY KEY,
  template_id   TEXT NOT NULL,
  version_label TEXT NOT NULL,
  rel_path      TEXT NOT NULL,
  sha256        TEXT NOT NULL,
  size_bytes    INTEGER NOT NULL,
  note          TEXT,
  created_by    TEXT,
  created_at    TEXT NOT NULL,
  FOREIGN KEY (template_id) REFERENCES quote_templates(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS quote_template_files_template ON quote_template_files (template_id);

-- ---------------------------------------------------------------------------
-- Enquiries, audit, usage, throttling
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS enquiries (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  email       TEXT NOT NULL,
  phone       TEXT,
  message     TEXT NOT NULL,
  source      TEXT NOT NULL DEFAULT 'contact',
  handled     INTEGER NOT NULL DEFAULT 0,
  handled_by  TEXT,
  handled_at  TEXT,
  ip_hash     TEXT,
  created_at  TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS enquiries_handled ON enquiries (handled, created_at);

-- Append-only. There is no update and no delete route for this table, by design.
CREATE TABLE IF NOT EXISTS audit_events (
  id           TEXT PRIMARY KEY,
  at           TEXT NOT NULL,
  actor_id     TEXT,
  actor_email  TEXT NOT NULL,
  action       TEXT NOT NULL,
  target_type  TEXT NOT NULL,
  target_id    TEXT NOT NULL,
  summary      TEXT NOT NULL,
  detail_json  TEXT
);

CREATE INDEX IF NOT EXISTS audit_events_at ON audit_events (at);
CREATE INDEX IF NOT EXISTS audit_events_target ON audit_events (target_type, target_id);

CREATE TABLE IF NOT EXISTS usage_events (
  id          TEXT PRIMARY KEY,
  at          TEXT NOT NULL,
  kind        TEXT NOT NULL,               -- page_view | quote_created | revision_saved | mail_sent
  tenant_id   TEXT,
  user_id     TEXT,
  ip_hash     TEXT,
  detail_json TEXT
);

CREATE INDEX IF NOT EXISTS usage_events_kind_at ON usage_events (kind, at);

-- Rate-limit counters. A row per key per window; the window is part of the key so
-- a stale row cannot extend a limit.
CREATE TABLE IF NOT EXISTS rate_limits (
  key         TEXT PRIMARY KEY,
  count       INTEGER NOT NULL,
  window_end  TEXT NOT NULL
);
